import React, { createContext, useContext, useState, ReactNode } from 'react';
import { FileInfo } from '../types';

interface FileContextType {
  files: FileInfo[];
  selectedFiles: string[];
  addFiles: (files: FileInfo[]) => void;
  removeFile: (fileId: string) => void;
  selectFile: (fileId: string) => void;
  selectAllFiles: () => void;
  clearSelection: () => void;
  isFileSelected: (fileId: string) => boolean;
  getSelectedFiles: () => FileInfo[];
}

const FileContext = createContext<FileContextType | undefined>(undefined);

interface FileProviderProps {
  children: ReactNode;
}

export function FileProvider({ children }: FileProviderProps) {
  const [files, setFiles] = useState<FileInfo[]>([]);
  const [selectedFiles, setSelectedFiles] = useState<string[]>([]);

  const addFiles = (newFiles: FileInfo[]) => {
    setFiles(prev => [...prev, ...newFiles]);
  };

  const removeFile = (fileId: string) => {
    setFiles(prev => prev.filter(file => file.id !== fileId));
    setSelectedFiles(prev => prev.filter(id => id !== fileId));
  };

  const selectFile = (fileId: string) => {
    setSelectedFiles(prev => 
      prev.includes(fileId) 
        ? prev.filter(id => id !== fileId)
        : [...prev, fileId]
    );
  };

  const selectAllFiles = () => {
    setSelectedFiles(files.map(file => file.id));
  };

  const clearSelection = () => {
    setSelectedFiles([]);
  };

  const isFileSelected = (fileId: string) => {
    return selectedFiles.includes(fileId);
  };

  const getSelectedFiles = () => {
    return files.filter(file => selectedFiles.includes(file.id));
  };

  return (
    <FileContext.Provider
      value={{
        files,
        selectedFiles,
        addFiles,
        removeFile,
        selectFile,
        selectAllFiles,
        clearSelection,
        isFileSelected,
        getSelectedFiles,
      }}
    >
      {children}
    </FileContext.Provider>
  );
}

export function useFile() {
  const context = useContext(FileContext);
  if (context === undefined) {
    throw new Error('useFile must be used within a FileProvider');
  }
  return context;
}
